package com.example.qldetai.feature.evaluation;
import com.example.qldetai.feature.identity.Lecturer; import jakarta.persistence.*; import lombok.*;
@Entity @Table(name="committee_members") @Getter @Setter @NoArgsConstructor public class CommitteeMember { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="committee_id") private EvaluationCommittee committee; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="lecturer_id") private Lecturer lecturer; @Column(name="slot_no",nullable=false) private int slotNo; @Enumerated(EnumType.STRING) @Column(name="committee_role",nullable=false) private CommitteeRole committeeRole; }
